              or ArgumentList/*[1][self::StringLiteral or self::NumericLiteral or self::CharLiteral])])
      or exists($chain($s)/self::MethodCall[@MethodName = ('range', 'rangeClosed')][*[1][self::TypeExpression]]
           [not(ArgumentList/*[$mentionsSize(.)])])
      or exists($chain($s)/(self::ArrayAllocation[ArrayInitializer] | self::ArrayInitializer))
    },
    $chunkVariable := function($s) {
      let $root := $chain($s)/self::VariableAccess
      return exists($root) and (
        (let $declared := $root/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration][1]
                            //VariableDeclarator[VariableId/@Name = $root/@Name]
         return exists($declared) and (every $d in $declared satisfies $windowed($d/*[2])))
        or (let $fields := $root/ancestor::ClassBody[1]/FieldDeclaration[pmd-java:modifiers() = 'final']
                             /VariableDeclarator[VariableId/@Name = $root/@Name]
            return exists($fields) and (every $d in $fields satisfies $fixedChain($d/*[2])))
        or
        exists($root/ancestor::ForeachStatement[LocalVariableDeclaration/VariableDeclarator/VariableId/@Name = $root/@Name]
                 [$partitioned(*[2])])
        or exists($root/ancestor::LambdaExpression[LambdaParameterList/LambdaParameter/VariableId/@Name = $root/@Name]
                 [parent::ArgumentList/parent::MethodCall[@MethodName = ('forEach', 'map')]]
                 [$partitioned(parent::ArgumentList/parent::MethodCall/*[1])]))
    },
    $collection := function($r) {
      $r[pmd-java:typeIs('java.util.Collection') or pmd-java:typeIs('java.util.Map')
         or pmd-java:typeIs('java.lang.Iterable') or pmd-java:typeIs('java.util.stream.BaseStream')]
    },
    $publisher := function($r) {
      $r[pmd-java:typeIs('reactor.core.publisher.Flux') or pmd-java:typeIs('reactor.core.publisher.Mono')]
    },
    $grouped := function($s) {
      exists($chain($s)/self::MethodCall[@MethodName = ('buffer', 'bufferTimeout', 'bufferUntil', 'bufferWhile',
        'window', 'windowTimeout', 'windowUntil', 'windowWhile', 'collectList', 'collectMap', 'reduce')])
      or $sized($s, ('take', 'limitRequest'))
    },
    $fromCollection := function($s) {
      not($grouped($s))
      and exists($chain($s)/self::MethodCall[@MethodName = ('fromIterable', 'fromStream', 'fromArray')]
            [*[1][self::TypeExpression][pmd-java:typeIs('reactor.core.publisher.Flux')]]
            [ArgumentList/@Size = 1]
            [not($fixedChain(ArgumentList/*[1])) and not($chunkVariable(ArgumentList/*[1]))])
    },
    $perElement := function($e) {
      exists($chain($e)/self::MethodCall[@MethodName = ('map', 'flatMap', 'mapToObj')][$collection(*[1])]
               [$worker(ArgumentList/*[1])])
      and not($fixedChain($e)) and not($chunkVariable($e))
    }
return (
  //MethodCall[@MethodName = ('flatMap', 'flatMapSequential')][ArgumentList/@Size = 1]
    [*[1][pmd-java:typeIs('reactor.core.publisher.Flux')]]
    [$fromCollection(*[1])]
    [$worker(ArgumentList/*[1])]
  | //MethodCall[@MethodName = ('zip', 'zipDelayError', 'when', 'whenDelayError')
                 or (@MethodName = ('merge', 'mergeSequential') and ArgumentList/@Size = 1)]
      [*[1][self::TypeExpression][$publisher(.)]]
      [let $sources := ArgumentList/*[1],
           $built := ($sources, $sources/self::VariableAccess
                        /ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::LambdaExpression][1]
                        //VariableDeclarator[VariableId/@Name = $sources/@Name]/*[2])
       return some $e in $built satisfies $perElement($e)]
)

//MethodCall[pmd-java:matchesSig('java.util.concurrent.Executors#newCachedThreadPool(_*)')]
| //ConstructorCall[pmd-java:typeIs('java.util.concurrent.ThreadPoolExecutor')]
    [ArgumentList/*[2][self::FieldAccess[@Name = 'MAX_VALUE'][TypeExpression[pmd-java:typeIs('java.lang.Integer')]]]]

let $caught := ('IllegalArgumentException', 'RuntimeException', 'Exception', 'Throwable')
return (
  //MethodCall[pmd-java:matchesSig('java.net.URI#create(java.lang.String)')]
    [not(ArgumentList/*[1][@CompileTimeConstant = true()])]
  | //MethodReference[@MethodName = 'create'][*[1][self::TypeExpression][pmd-java:typeIsExactly('java.net.URI')]]
)[let $scope := ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::Initializer
                             or self::FieldDeclaration or self::EnumConstant
                             or self::CompactConstructorDeclaration][1]
   return not(ancestor::*[self::Block or self::ResourceList]
                [parent::TryStatement/CatchClause/CatchParameter/descendant::ClassType[@SimpleName = $caught]]
                [$scope << .])]
